// The onboarding record panels (fields, voice answers, prices, services, launch towns, the page map, the
// by-hand set-up), ported from public/client-record.html for the new shell (27 Oct 2026). Generated by
// the port script in the UI redesign; behaviour unchanged. A classic script: window.RecordPanels.mount(container, clientId, panel).


  let clientId = null; let PANEL = 'overview'; let FIELD = null; let CONTAINER = null;
  // Elements the old header had (title, badges, score ring, review and archive buttons) may not exist in the new shell: a dummy swallows the writes
  const dummy = new Proxy(function () {}, { get: (t, k) => (k === Symbol.toPrimitive ? () => '' : dummy), set: () => true, apply: () => dummy });
  const byId = id => (CONTAINER && CONTAINER.querySelector('#' + id)) || document['getElementById'](id) || dummy;
  let rec = null;
  let editing = null;          // field key being edited
  let priceEdit = null;        // price row id being edited, or 'new'
  const openOptional = new Set();  // panels whose optional blanks are expanded
  const openTranscript = new Set();

  const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const fmt = s => s ? new Date(s).toLocaleString('en-GB', { day:'numeric', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' }) : '';
  const setSaved = (t, cls) => { const el = byId('saved'); el.textContent = t || ''; el.className = 'saved ' + (cls || ''); };
  const gbp = n => n == null ? '' : '£' + Number(n).toLocaleString('en-GB');
  const allFields = () => rec.sections.flatMap(s => s.fields);
  const byKey = k => allFields().find(f => f.key === k);
  // Render units: a voice+typed pair and the accreditations show as one block. The service
  // tick groups share the completeness group "services" but each shows on its own.
  const unitFields = f => f.group && f.group !== 'services' ? allFields().filter(x => x.group === f.group) : [f];

  // ── Routing: #panel or #panel:field_key ──
  const PANEL_KEYS = () => ['overview', ...rec.panels.map(p => p.key), 'pages', 'original'];
  function current() { return { panel: PANEL_KEYS().includes(PANEL) ? PANEL : 'overview', field: FIELD }; }
  function go(target) { const [p, f] = String(target).split(':'); PANEL = p; FIELD = f || null; editing = null; priceEdit = null; if (PANEL === 'pages') loadPagePreview(); render(); FIELD = null; if (window.RecordPanels && window.RecordPanels.onPanel) window.RecordPanels.onPanel(PANEL); }

  async function load() {
    const res = await fetch(`/api/clients/${clientId}/record`);
    if (!res.ok) { byId('main').innerHTML = `<div class="empty">Could not load: ${esc((await res.json().catch(() => ({}))).error || res.status)}</div>`; return; }
    rec = await res.json();
    await Promise.all([loadServices(), loadPageMap(), rec.submissions.length ? null : loadByHand()]);
    loadBalance();
    if (current().panel === 'pages') loadPagePreview();
    const c = rec.client;
    void `${c.name} — Onboarding record`;
    byId('crumbClient').textContent = c.name; byId('crumbClient').href = `/clients/${c.id}`;
    byId('clientLink').href = `/clients/${c.id}`;
    byId('title').textContent = c.name;
    byId('badges').innerHTML = (c.source === 'fillout' ? (c.reviewedAt ? '<span class="badge b-ok">From Fillout</span> ' : '<span class="badge b-warn">From Fillout, unreviewed</span> ') : '') + (c.archivedAt ? '<span class="badge b-muted">Archived</span>' : '');
    const last = rec.submissions[0];
    byId('sub').innerHTML = `${esc(rec.niche || 'Niche not given')}${rec.niche && !rec.nicheKnown ? ' <span class="badge b-warn">No field map for this niche</span>' : ''}` + (last ? ` · ${rec.submissions.length} submission${rec.submissions.length > 1 ? 's' : ''}, last ${fmt(last.receivedAt)}` : '');
    if (c.source === 'fillout') {
      const rb = byId('reviewBtn'); rb.style.display = ''; rb.textContent = c.reviewedAt ? 'Mark unreviewed' : 'Mark reviewed';
      const ab = byId('archiveBtn'); ab.style.display = ''; ab.textContent = c.archivedAt ? 'Unarchive' : 'Archive';
      if (last) byId('reprocessBtn').style.display = '';
    }
    const k = rec.completeness;
    byId('score').style.display = ''; byId('ring').style.setProperty('--p', k.pct);
    byId('scoreText').innerHTML = `Ready to build ${k.needed.filled} of ${k.needed.total}<span class="ring2">Worth chasing ${k.chase.filled} of ${k.chase.total}</span>`;
    render();
  }
  // Notes written by the model are read by a person: field names become plain words (the API does this too)
  const human = s => String(s == null ? '' : s).replace(/\bfrom_gbp\b/gi, 'lowest price').replace(/\bup_to_gbp\b/gi, 'highest price').replace(/\btypical_gbp\b/gi, 'single price');

  // ── Menu ──
  function renderMenu() {
    const cur = current().panel;
    const att = rec.attention || [];
    const groups = [];
    for (const p of rec.panels) { let g = groups.find(x => x.name === p.group); if (!g) { g = { name: p.group, items: [] }; groups.push(g); } g.items.push(p); }
    const item = (key, label, cnt, dot) => `<div class="mi${cur === key ? ' active' : ''}" onclick="go('${key}')"><span class="dot ${dot}"></span><span class="lbl">${esc(label)}</span><span class="cnt">${cnt}</span></div>`;
    const ovDot = att.some(a => a.group === 'blocks') ? 'missing' : att.length ? 'chase' : 'complete';
    const counts = p => p.needed.total ? `${p.needed.filled} of ${p.needed.total}` : p.chase.total ? `${p.chase.filled} of ${p.chase.total} chase` : (p.optional.total ? `${p.optional.filled} of ${p.optional.total} opt` : '');
    let html = item('overview', 'Overview', att.length ? `${att.length} to check` : 'ready', ovDot);
    for (const g of groups) {
      html += `<div class="mg">${esc(g.name)}</div>`;
      for (const p of g.items) html += item(p.key, p.label, counts(p), p.status);
    }
    const live = pm.rows.filter(r => r.applies);
    const needH1 = live.filter(r => r.h1_source === 'conflict' && !r.h1).length;
    html += `<div class="mg">Build</div>` + item('pages', 'Pages', live.length ? `${live.length} pages${needH1 ? ` · ${needH1} need H1` : ''}` : 'not mapped', live.length ? (needH1 ? 'chase' : 'complete') : 'none');
    html += `<details class="orig"${cur === 'original' ? ' open' : ''}><summary>Original answers</summary>${item('original', 'By form page', `${allFields().length} fields`, 'none')}</details>`;
    byId('menu').innerHTML = html;
    const sel = byId('menuSelect');
    sel.innerHTML = `<option value="overview">Overview</option>` + groups.map(g => `<optgroup label="${esc(g.name)}">${g.items.map(p => `<option value="${p.key}">${esc(p.label)} (${counts(p) || 'optional'})</option>`).join('')}</optgroup>`).join('') + `<optgroup label="Build"><option value="pages">Pages (${live.length || 'not mapped'})</option></optgroup><option value="original">Original answers</option>`;
    sel.value = cur;
  }

  function render() {
    renderMenu();
    const { panel, field } = current();
    const main = byId('main');
    if (panel === 'overview') main.innerHTML = renderOverview();
    else if (panel === 'original') main.innerHTML = renderOriginal();
    else if (panel === 'pages') main.innerHTML = renderPageMap();
    else main.innerHTML = renderPanel(rec.panels.find(p => p.key === panel));
    if (field) { const el = byId('f_' + CSS.escape(field)); if (el) { el.scrollIntoView({ block: 'center' }); el.classList.add('hl'); } }
    const ed = byId('ed'); if (ed) ed.focus();
  }

  // ── Overview ──
  function renderOverview() {
    const k = rec.completeness, last = rec.submissions[0];
    const att = rec.attention || [];
    const dup = rec.duplicateOf ? `<div class="stat"><div class="k">Possible duplicate</div><div class="v small">of ${esc(rec.duplicateOf.name || 'another client')}</div></div>` : '';
    const stats = `<div class="stats">
      <div class="stat"><div class="k">Ready to build</div><div class="v">${k.needed.filled} of ${k.needed.total}</div><div class="pnote">needed answers · ${k.pct}%</div></div>
      <div class="stat"><div class="k">Worth chasing</div><div class="v">${k.chase.filled} of ${k.chase.total}</div></div>
      <div class="stat"><div class="k">Optional filled</div><div class="v">${k.optional.filled} of ${k.optional.total}</div></div>
      <div class="stat"><div class="k">Submitted</div><div class="v small">${last ? esc(fmt(last.receivedAt)) : '—'}</div></div>
      <div class="stat"><div class="k">Submission id</div><div class="v small">${last ? esc(last.submissionId) : '—'}</div></div>
      ${dup}</div>`;
    const item = a => {
      const to = a.field ? `${a.panel}:${a.field}` : a.panel;
      const fields = a.fields ? `<div class="sub">${a.fields.map(f => `<a href="#${a.panel}:${esc(f.key)}">${esc(f.label)}</a>`).join(' · ')}</div>` : '';
      const action = a.action === 'retry' ? ` <button class="btn btn-ghost btn-xs" onclick="extractPrices()">Retry</button>` : a.code === 'submission_error' ? ` <a class="btn btn-ghost btn-xs" href="/clients">Open inbox</a>` : '';
      return `<div class="ai ${a.group === 'blocks' ? 'bad' : 'chase'}"><span class="sev"></span><div class="m"><a href="#${esc(to)}">${esc(human(a.msg))}</a>${action}${fields}</div></div>`;
    };
    const blocks = att.filter(a => a.group === 'blocks'), chase = att.filter(a => a.group !== 'blocks');
    let list;
    if (!att.length) list = `<div class="ready">✓ Ready to build. Nothing needs attention; mark the record reviewed when you have read it.</div>`;
    else list = (blocks.length ? `<div class="att-group">Blocks the build</div>${blocks.map(item).join('')}` : `<div class="ready">✓ Ready to build: every needed answer is in.</div>`)
      + (chase.length ? `<div class="att-group">Worth chasing</div>${chase.map(item).join('')}` : '');
    return `<div class="panel"><div class="ph"><h2>Overview</h2><p>Where this record stands and what still needs a person.</p></div>${stats}<div class="att"><h3>Needs attention</h3>${list}</div></div>`;
  }

  // ── A panel ──
  function renderPanel(p) {
    const fields = allFields().filter(f => f.panel === p.key);
    const head = `<div class="ph"><h2>${esc(p.label)} <span class="tag ${p.tag.toLowerCase()}">${p.tag}</span></h2><p>${esc(p.description)}</p>
      <div class="pc">${p.needed.total ? `Needed ${p.needed.filled} of ${p.needed.total}` : 'Nothing needed here'}${p.chase.total ? ` · worth chasing ${p.chase.filled} of ${p.chase.total}` : ''}${p.optional.total ? ` · optional ${p.optional.filled} of ${p.optional.total}` : ''}${p.notApplicable ? ` · ${p.notApplicable} not applicable` : ''}</div></div>`;
    let body = '';
    if (p.key === 'prices') body += renderPrices(rec.prices);
    if (p.key === 'services' && byHand && !byHand.hasFillout) body += renderByHand(byHand);
    if (p.key === 'services') body += renderServices(services);
    if (p.key === 'areas') body += renderLaunchTowns();
    body += `<div class="fields">${renderFieldList(p.key, fields)}</div>`;
    return `<div class="panel">${head}${body}</div>`;
  }

  // Fields of a panel: units (pairs, the accreditations) rendered once; optional blanks collapsed
  function renderFieldList(panelKey, fields) {
    const done = new Set();
    const shown = [], optionalBlank = [];
    for (const f of fields) {
      if (done.has(f.key)) continue;
      const unit = unitFields(f).filter(x => fields.includes(x));
      unit.forEach(x => done.add(x.key));
      const filled = unit.some(x => x.status === 'filled');
      const optional = unit.every(x => x.optional);
      if (optional && !filled && f.group !== 'accreditations') optionalBlank.push(unit);
      else shown.push(unit);
    }
    let html = shown.map(u => renderUnit(u)).join('');
    if (optionalBlank.length) {
      const open = openOptional.has(panelKey);
      html += `<div class="opt-line" onclick="toggleOptional('${panelKey}')">${open ? '▾' : '▸'} ${optionalBlank.length} optional field${optionalBlank.length === 1 ? '' : 's'} not provided</div>`;
      if (open) html += optionalBlank.map(u => renderUnit(u)).join('');
    }
    return html || '<div class="empty">No fields on this panel.</div>';
  }
  function toggleOptional(k) { if (openOptional.has(k)) openOptional.delete(k); else openOptional.add(k); render(); }

  function renderUnit(unit) {
    if (unit[0].group === 'accreditations') return renderAccreditations(unit);
    const voice = unit.find(f => f.type === 'AudioRecording');
    if (voice) return renderVoice(voice, unit.find(f => f !== voice) || null);
    return renderField(unit[0]);
  }

  const srcTag = f => f.source === 'manual' ? '<small class="src manual">edited by hand</small>' : f.source === 'transcript' ? '<small class="src">from recording</small>' : f.status === 'filled' ? '<small class="src">from form</small>' : '';
  const stripVT = l => String(l).replace(/\s*\((voice|typed)\)\s*$/, '');

  function showValue(f) {
    if (f.applicable === false && f.status !== 'filled') return '<div class="val blank">Not applicable</div>';
    if (f.status !== 'filled') return '<div class="val blank">Not provided — click to add</div>';
    const v = f.value;
    if (Array.isArray(v)) return `<div class="val"><ul>${v.map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>`;
    if (v && typeof v === 'object') return `<div class="val">${esc(JSON.stringify(v))}</div>`;
    if (f.type === 'URLInput' && /^https?:\/\//i.test(String(v))) return `<div class="val"><a href="${esc(v)}" target="_blank" rel="noopener">${esc(v)}</a></div>`;
    return `<div class="val">${esc(v)}</div>`;
  }
  const isList = f => f.type === 'Checkboxes' || f.type === 'MultiSelect' || Array.isArray(f.value);

  const tierTag = f => f.tier === 'needed' ? 'needed' : f.tier === 'optional' ? 'optional' : 'worth chasing';
  function renderField(f, opts = {}) {
    const label = opts.label || f.label;
    const flags = [f.applicable === false ? 'not applicable' : tierTag(f), srcTag(f)].filter(Boolean).join(' · ');
    const help = f.help ? `<div class="help">${esc(f.help)}</div>` : '';
    let body;
    if (f.type === 'Checkbox') body = `<label class="tick"><input type="checkbox" ${f.value === true ? 'checked' : ''} onchange="saveField('${f.key}', this.checked)"> <span>${f.value === true ? 'Received' : 'Not yet received'}</span></label>`;
    else if (editing === f.key) body = renderEditor(f);
    else if (f.group === 'services' && f.status === 'filled' && Array.isArray(f.value)) body = `<div class="chips" onclick="startEdit('${f.key}')" title="Click to edit">${f.value.map(x => `<span class="chip">${esc(x)}</span>`).join('')}</div>`;
    else if (f.type === 'Dropdown' && f.key === 'niche') body = `<div class="chips"><span class="chip">${esc(f.value || 'Not given')}</span></div>`;
    else body = `<div onclick="startEdit('${f.key}')" title="Click to edit">${showValue(f)}</div>`;
    return `<div class="f" id="f_${esc(f.key)}"><div class="lab"><span>${esc(label)}</span><small>${flags}</small></div>${help}${body}</div>`;
  }
  function renderEditor(f) {
    const multi = f.type === 'LongAnswer' || isList(f);
    const cur = Array.isArray(f.value) ? f.value.join('\n') : (f.value == null || typeof f.value === 'object' ? '' : String(f.value));
    const hint = isList(f) ? 'One item per line. ' : '';
    return `${multi ? `<textarea id="ed" data-key="${esc(f.key)}" data-list="${isList(f) ? 1 : 0}" onkeydown="edKey(event)" onblur="edBlur(event)">${esc(cur)}</textarea>` : `<input type="text" id="ed" data-key="${esc(f.key)}" data-list="0" value="${esc(cur)}" onkeydown="edKey(event)" onblur="edBlur(event)">`}
      <div class="ehint">${hint}${multi ? 'Click away to save' : 'Enter to save'}, Escape to cancel.</div>`;
  }
  function startEdit(key) { const f = byKey(key); if (!f || f.type === 'AudioRecording' || f.key === 'niche') return; editing = key; render(); }
  let cancelling = false;
  function edKey(e) {
    if (e.key === 'Escape') { cancelling = true; editing = null; render(); cancelling = false; }
    else if (e.key === 'Enter' && e.target.tagName === 'INPUT') { e.preventDefault(); e.target.blur(); }
  }
  async function edBlur(e) {
    if (cancelling) return;
    const el = e.target, key = el.dataset.key, f = byKey(key);
    let value = el.value;
    if (el.dataset.list === '1') value = value.split('\n').map(s => s.trim()).filter(Boolean);
    const before = Array.isArray(f.value) ? f.value.join('\n') : (f.value == null || typeof f.value === 'object' ? '' : String(f.value));
    const after = Array.isArray(value) ? value.join('\n') : value;
    if (after.trim() === before.trim()) { editing = null; render(); return; }
    await saveField(key, value);
  }
  async function saveField(key, value) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/record/${encodeURIComponent(key)}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value }) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1800);
    editing = null; await load();
  }

  // Voice card: player, transcript toggle (open when there is no typed twin), the typed twin beneath
  function renderVoice(voice, typed) {
    const a = voice.audio;
    const label = stripVT(voice.label);
    const hasTyped = typed && typed.status === 'filled';
    const open = openTranscript.has(voice.key) || !hasTyped;
    const transcript = (a && a.transcription) || (voice.value && voice.value.transcription) || '';
    // Nothing recorded and nothing typed: one compact row instead of an empty card
    if (voice.status !== 'filled' && !a && (!typed || typed.status !== 'filled') && !(typed && editing === typed.key)) {
      const tag = [voice.optional ? 'optional' : tierTag(voice)].join('');
      return `<div class="f compact" id="f_${esc(voice.key)}"><div><div class="lab"><span>${esc(label)}</span></div><div class="val blank">Not provided <small>· voice or typed · ${tag}</small></div></div>${typed ? `<button class="btn btn-ghost btn-xs" onclick="startEdit('${typed.key}')">Type an answer</button>` : ''}</div>`;
    }
    let inner = '';
    if (voice.status !== 'filled' && !a) inner = `<div class="vm">No recording</div>`;
    else {
      if (a && a.playable) inner += `<audio controls preload="none" src="/api/clients/${clientId}/audio/${a.id}"></audio><div class="vm"><span>Our copy${a.duration ? `, ${a.duration}s` : ''}${a.size ? `, ${Math.round(a.size / 1024)} KB` : ''}</span>${transcript ? `<button class="linkish" onclick="toggleTranscript('${voice.key}')">${open ? 'Hide' : 'Show'} transcript</button>` : '<span>No transcript</span>'}</div>`;
      else if (a && a.downloadStatus === 'failed') inner += `<div class="vm"><span class="badge b-bad">Audio copy failed</span><span>${esc(a.downloadError || '')}</span>${a.filloutUrl ? `<a href="${esc(a.filloutUrl)}" target="_blank" rel="noopener">Fillout link</a>` : ''}${transcript ? `<button class="linkish" onclick="toggleTranscript('${voice.key}')">${open ? 'Hide' : 'Show'} transcript</button>` : ''}</div>`;
      else inner += `<div class="vm"><span>Not yet copied</span>${a && a.filloutUrl ? `<a href="${esc(a.filloutUrl)}" target="_blank" rel="noopener">Fillout link</a>` : ''}${transcript ? `<button class="linkish" onclick="toggleTranscript('${voice.key}')">${open ? 'Hide' : 'Show'} transcript</button>` : ''}</div>`;
      if (open && transcript) inner += `<div class="tr">${esc(transcript)}</div>`;
    }
    if (typed) {
      const tBody = editing === typed.key ? renderEditor(typed) : `<div onclick="startEdit('${typed.key}')" title="Click to edit">${showValue(typed)}</div>`;
      inner += `<div class="typed" id="f_${esc(typed.key)}"><div class="tl">Typed answer ${srcTag(typed)}</div>${tBody}</div>`;
    }
    const flags = [voice.optional ? 'optional' : '', srcTag(voice)].filter(Boolean).join(' · ');
    return `<div class="f" id="f_${esc(voice.key)}"><div class="lab"><span>${esc(label)}</span><small>voice answer${flags ? ' · ' + flags : ''}</small></div>${voice.help ? `<div class="help">${esc(voice.help)}</div>` : ''}<div class="voice">${inner}</div></div>`;
  }
  function toggleTranscript(k) { if (openTranscript.has(k)) openTranscript.delete(k); else openTranscript.add(k); render(); }

  // The five accreditation triples as one table; each cell editable
  function renderAccreditations(unit) {
    const rows = [1, 2, 3, 4, 5].map(n => ({ n, scheme: unit.find(f => f.key === `accreditation_${n}_scheme`), number: unit.find(f => f.key === `accreditation_${n}_number`), link: unit.find(f => f.key === `accreditation_${n}_link`) }));
    const cell = f => !f ? '<td></td>' : editing === f.key ? `<td>${renderEditor(f)}</td>` : `<td id="f_${esc(f.key)}" onclick="startEdit('${f.key}')" title="Click to edit">${f.status === 'filled' ? (f.type === 'URLInput' ? `<a href="${esc(f.value)}" target="_blank" rel="noopener">${esc(f.value)}</a>` : esc(f.value)) : '<span class="val blank">—</span>'}${f.source === 'manual' ? ' <small class="src manual">edited</small>' : ''}</td>`;
    const any = unit.some(f => f.status === 'filled');
    return `<div class="f" id="f_accreditation_1_scheme"><div class="lab"><span>Accreditations and memberships</span><small>optional · ${any ? 'from form' : 'none given'}</small></div><div class="help">Gas Safe, NICEIC, Checkatrade and similar: scheme, membership number and a link to the listing.</div>
      <table class="t"><thead><tr><th>#</th><th>Scheme</th><th>Membership or registration number</th><th>Link to listing</th></tr></thead><tbody>${rows.map(r => `<tr><td class="num">${r.n}</td>${cell(r.scheme)}${cell(r.number)}${cell(r.link)}</tr>`).join('')}</tbody></table></div>`;
  }

  // ── Original answers: the fields as the form pages hold them ──
  function renderOriginal() {
    return `<div class="panel"><div class="ph"><h2>Original answers <span class="tag optional">By form page</span></h2><p>Every field we use for ${esc(rec.niche || 'this niche')}, in the order of the Fillout form pages.</p></div>` +
      rec.sections.map(s => `<div class="orig-section"><h2>${esc(s.name)}<span>${s.fields.filter(f => f.applicable !== false && f.status === 'filled').length} of ${s.fields.filter(f => f.applicable !== false).length} fields</span></h2><div class="fields">${renderFieldList('orig:' + s.name, s.fields)}</div></div>`).join('') + `</div>`;
  }

  // ── Service prices card (fillout/prices.js) ──
  function renderPrices(p) {
    if (!p) return '';
    const st = p.state || {};
    const flags = p.flags.map(f => `<span class="badge ${f.code === 'no_prices' ? 'b-muted' : f.code === 'unverified' ? 'b-bad' : 'b-warn'}">${esc(f.msg)}</span>`).join('');
    let stateLine = '';
    if (st.status === 'extraction_failed') stateLine = `<span class="badge b-bad">Extraction failed</span> <span class="pnote">${esc(st.error || '')}</span>`;
    else if (st.status === 'pending') stateLine = `<span class="badge b-muted">Extracting…</span>`;
    else if (st.status === 'no_transcript') stateLine = `<span class="badge b-muted">No prices recording</span>`;
    else if (st.status === 'not_applicable') stateLine = `<span class="badge b-ok">Prices marked not applicable</span>`;
    else if (st.transcriptChanged) stateLine = `<span class="badge b-warn">Transcript changed since extraction</span>`;
    const canExtract = p.transcript && p.transcript.trim();
    const head = `<div class="prices-head"><h3>Service prices</h3><div class="pt-actions">
      ${canExtract ? `<button class="btn btn-ghost btn-xs" onclick="extractPrices()">${st.status === 'extraction_failed' ? 'Retry' : 'Re-extract'}</button>` : ''}
      <button class="btn btn-ghost btn-xs" onclick="priceEdit='new';render()">Add row</button>
      <button class="btn btn-ghost btn-xs" onclick="pricesNotApplicable(${st.status === 'not_applicable' ? 'false' : 'true'})">${st.status === 'not_applicable' ? 'Clear not applicable' : 'Mark not applicable'}</button>
    </div></div>`;
    const rows = p.rows.map(r => priceEdit === r.id ? renderPriceEditor(r) : renderPriceRow(r)).join('') + (priceEdit === 'new' ? renderPriceEditor({ id: 'new', service: '', unit: '' }) : '');
    const table = `<table class="t"><thead><tr><th>Service</th><th>From</th><th>Up to / typical</th><th>Unit</th><th>What moves the price</th><th></th></tr></thead><tbody>${rows || `<tr><td colspan="6" class="val blank">${st.status === 'done' ? 'No prices given' : 'No rows yet'}</td></tr>`}</tbody></table>`;
    const transcript = `<div class="ptranscript"><h4>Transcript</h4>${p.transcript ? esc(p.transcript) : '<span class="val blank">No recording</span>'}</div>`;
    return `<div class="prices" id="f_prices">${head}<div class="prices-flags">${stateLine}${flags}</div><div class="prices-grid"><div class="ptable">${table}</div>${transcript}</div></div>`;
  }
  function priceBadges(r) {
    const b = [];
    if (r.quote_only) b.push('<span class="rb badge b-muted">quote only</span>');
    if (r.inferred) b.push(`<span class="rb badge b-warn" title="${esc(human(r.inferred_note || ''))}">inferred</span>`);
    if (r.unverified) b.push('<span class="rb badge b-bad" title="This number could not be traced to the transcript">unverified</span>');
    if (r.matched_to) b.push(`<span class="rb badge b-ok">matches ${esc(/most_wanted_(job_)?(\d)/.test(r.matched_to.key) ? 'your most-wanted job ' + r.matched_to.key.match(/(\d)$/)[1] : 'a ticked service')}: ${esc(r.matched_to.value)}</span>`);
    if (r.source === 'manual') b.push('<span class="rb badge b-warn">edited by hand</span>');
    return b.length ? `<div>${b.join('')}</div>` : '';
  }
  function renderPriceRow(r) {
    const upto = r.up_to_gbp != null ? gbp(r.up_to_gbp) : r.typical_gbp != null ? `${gbp(r.typical_gbp)} <span class="pnote">typical</span>` : '';
    return `<tr class="${r.source === 'manual' ? 'manual' : ''}">
      <td>${esc(r.service)}${priceBadges(r)}${r.inferred && r.inferred_note ? `<div class="pnote">${esc(human(r.inferred_note))}</div>` : ''}</td>
      <td class="num">${gbp(r.from_gbp)}</td><td class="num">${upto}</td><td>${esc(r.unit || '')}</td><td>${esc(human(r.what_moves_price || ''))}</td>
      <td class="pt-actions"><button class="btn btn-ghost btn-xs" onclick="priceEdit='${r.id}';render()">Edit</button><button class="btn btn-ghost btn-xs" onclick="deletePriceRow('${r.id}')">Delete</button></td></tr>`;
  }
  function renderPriceEditor(r) {
    const v = k => r[k] == null ? '' : esc(r[k]);
    return `<tr class="manual"><td><input type="text" id="pe_service" value="${v('service')}" placeholder="Service as spoken"><label class="pnote"><input type="checkbox" id="pe_quote_only" ${r.quote_only ? 'checked' : ''}> quote only</label></td>
      <td><input type="number" id="pe_from" value="${v('from_gbp')}" placeholder="from"></td>
      <td><input type="number" id="pe_upto" value="${v('up_to_gbp')}" placeholder="up to"><input type="number" id="pe_typical" value="${v('typical_gbp')}" placeholder="typical" style="margin-top:4px"></td>
      <td><input type="text" id="pe_unit" value="${v('unit')}" placeholder="per job"></td>
      <td><input type="text" id="pe_moves" value="${v('what_moves_price')}" placeholder="only if they said"></td>
      <td class="pt-actions"><button class="btn btn-primary btn-xs" onclick="savePriceRow('${r.id}')">Save</button><button class="btn btn-ghost btn-xs" onclick="priceEdit=null;render()">Cancel</button></td></tr>`;
  }
  const numOrNull = id => { const s = byId(id).value.trim(); return s === '' ? null : Number(s); };
  async function savePriceRow(id) {
    const body = { service: byId('pe_service').value, from_gbp: numOrNull('pe_from'), up_to_gbp: numOrNull('pe_upto'), typical_gbp: numOrNull('pe_typical'),
      unit: byId('pe_unit').value, what_moves_price: byId('pe_moves').value, quote_only: byId('pe_quote_only').checked };
    setSaved('Saving…');
    const res = await fetch(id === 'new' ? `/api/clients/${clientId}/prices` : `/api/clients/${clientId}/prices/${id}`, { method: id === 'new' ? 'POST' : 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1800);
    priceEdit = null; await load();
  }
  async function deletePriceRow(id) {
    if (!confirm('Delete this price row? A re-extraction will not bring it back.')) return;
    const res = await fetch(`/api/clients/${clientId}/prices/${id}`, { method: 'DELETE' });
    if (!res.ok) { setSaved('Not deleted', 'bad'); return; }
    await load();
  }
  async function extractPrices() {
    setSaved('Extracting prices…');
    const res = await fetch(`/api/clients/${clientId}/prices/extract`, { method: 'POST' });
    const r = await res.json().catch(() => ({}));
    setSaved(r.error ? 'Extraction failed: ' + r.error : `Extracted ${r.rows || 0} row(s)`, r.error ? 'bad' : 'ok'); setTimeout(() => setSaved(''), 3000);
    await load();
  }
  async function pricesNotApplicable(value) {
    await fetch(`/api/clients/${clientId}/prices/not-applicable`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value }) });
    await load();
  }

  // ── Categories & services: the resolver's tabs, flags, primary selector, additional services ──
  let services = null;        // GET /api/clients/:id/services
  let svcTab = null;          // open category tab
  let changing = null;        // additional row id whose category is being changed
  let svcOutcomeFilter = 'all'; // all | page | absorbed | folded | excluded | mentioned | merged | missing (not in library) | flagged
  async function loadServices() {
    try { const res = await fetch(`/api/clients/${clientId}/services`); services = res.ok ? await res.json() : null; } catch (_) { services = null; }
  }
  function renderServices(s) {
    if (!s) return `<div class="prices"><div class="prices-head"><h3>Categories &amp; services</h3></div><div class="pm-box warn" style="margin:0">Could not load categories and services. Reload the page; if it stays, check the server log.</div></div>`;
    if (!s.hasConfig) return `<div class="prices" id="f_services_resolved"><div class="prices-head"><h3>Categories &amp; services</h3></div><div class="pm-box warn" style="margin:0"><h3>Services not set up for this niche yet</h3><div class="pnote">${esc(s.niche || 'No niche given')} has no services file (fillout/services/), so there are no category tabs and no page map. Any tick boxes below are still stored and will be used once the file is added.</div></div></div>`;
    const r = s.resolved;
    const flags = r.flags.filter(f => !f.code.startsWith('config_'));
    const configNotes = r.flags.filter(f => f.code.startsWith('config_'));
    const flagHtml = flags.map(f => `<span class="badge ${f.severity === 'bad' ? 'b-bad' : 'b-warn'}">${esc(f.msg)}</span>`).join('') + (configNotes.length ? `<span class="badge b-muted" title="${esc(configNotes.map(f => f.msg).join('\n'))}">${configNotes.length} note${configNotes.length === 1 ? '' : 's'} on the categories file</span>` : '');
    const primarySel = `<label class="pnote">Primary category <select onchange="setPrimary(this.value)"><option value=""${!s.primaryOverride ? ' selected' : ''}>Default (${esc((s.allCategories.find(c => c.key === s.primaryDefault) || {}).name || s.primaryDefault)})</option>${s.allCategories.map(c => `<option value="${esc(c.key)}"${s.primaryOverride === c.key ? ' selected' : ''}>${esc(c.name)}</option>`).join('')}</select>${s.primaryOverride ? ' <span class="src manual">set by hand</span>' : ''}</label>`;
    if (!svcTab || !r.categories.some(c => c.key === svcTab)) svcTab = r.primary || (r.categories[0] && r.categories[0].key) || null;
    const tc = s.tickCounts || [];
    const tcTotal = tc.reduce((a, c) => ({ ticked: a.ticked + c.ticked, total: a.total + c.total }), { ticked: 0, total: 0 });
    const tickHtml = tc.length ? `<div class="pnote" style="margin:.2rem 0 .6rem"><strong>${tcTotal.ticked} of ${tcTotal.total} ticked</strong> · ${tc.map(c => `${esc(c.name)} ${c.ticked} of ${c.total}`).join(' · ')}</div>` : '';
    const tabs = r.categories.map(c => `<button class="btn ${c.key === svcTab ? 'btn-primary' : 'btn-ghost'} btn-xs" onclick="svcTab='${c.key}';render()">${esc(c.name)}${c.primary ? ' ★' : ''} <span class="pnote" style="color:inherit">${c.rows.length}</span></button>`).join(' ');
    const cur = r.categories.find(c => c.key === svcTab);
    const rows = cur ? cur.rows.map(row => `<tr><td class="num">${esc(row.legacyKey)}</td><td>${esc(row.name)}${row.kind === 'additional' ? ' <span class="rb badge b-ok">additional</span>' : ''}</td><td>${row.kind === 'duplicate' ? `<span class="badge b-warn">duplicate</span> <span class="pnote">also on ${esc(row.alsoOn.map(a => a.name + (a.hasTab ? '' : ' (no tab)')).join(', '))}</span>` : row.kind === 'unique' ? '<span class="badge b-ok">unique</span>' : ''}</td></tr>`).join('') : '';
    const table = cur ? `<table class="t"><thead><tr><th>Key</th><th>Service</th><th>On this tab</th></tr></thead><tbody>${rows || '<tr><td colspan="3" class="val blank">No services on this tab</td></tr>'}</tbody></table>` : '<div class="val blank">No category tabs: nothing ticked yet.</div>';
    const addRows = (s.additional.rows || []).map(a => {
      const cat = key => (s.allCategories.find(c => c.key === key) || {}).name || key;
      const tabsOpts = r.categories.map(c => `<option value="${esc(c.key)}">${esc(c.name)}</option>`).join('');
      let right;
      if (a.status === 'covered') right = `<span class="badge b-muted">already covered</span>`;
      else if (a.status === 'confirmed') right = `<span class="badge b-ok">confirmed: ${esc(cat(a.confirmedCategoryKey))}</span> <button class="btn btn-ghost btn-xs" onclick="changing='${a.id}';render()">Change</button>`;
      else if (a.status === 'rejected' || a.status === 'skipped') right = `<span class="badge b-muted">${esc(a.status)}</span> <button class="btn btn-ghost btn-xs" onclick="changing='${a.id}';render()">Change</button>`;
      else if (a.status === 'extraction_failed') right = `<span class="badge b-bad">no proposal</span> <button class="btn btn-ghost btn-xs" onclick="changing='${a.id}';render()">Pick a category</button>`;
      else right = `${a.proposedCategoryKey ? `<span class="pnote">Proposed: <strong>${esc(cat(a.proposedCategoryKey))}</strong> · ${esc(a.reason || '')}</span> <button class="btn btn-primary btn-xs" onclick="decideAdditional('${a.id}', 'confirmed', '${esc(a.proposedCategoryKey)}')">Confirm</button>` : `<span class="pnote">Unsure${a.reason ? ' · ' + esc(a.reason) : ''}</span>`} <button class="btn btn-ghost btn-xs" onclick="changing='${a.id}';render()">Change</button> <button class="btn btn-ghost btn-xs" onclick="decideAdditional('${a.id}', 'skipped')">Skip</button>`;
      if (changing === a.id) right = `<select id="chg_${a.id}">${tabsOpts}</select> <button class="btn btn-primary btn-xs" onclick="decideAdditional('${a.id}', 'confirmed', byId('chg_${a.id}').value)">Confirm</button> <button class="btn btn-ghost btn-xs" onclick="changing=null;render()">Cancel</button>`;
      return `<tr class="${a.source === 'manual' ? 'manual' : ''}"><td>${esc(a.service)}${a.origin ? ` <span class="pnote">${esc(a.origin)}</span>` : ''}</td><td>${right}</td></tr>`;
    }).join('');
    const st = s.additional.state || {};
    const hasAdd = !!(s.additionalText || (s.additionalTicks || []).length);
    const addHead = `<div class="prices-head" style="margin-top:1rem"><h3>Additional services (ticked or typed on the form)</h3><div class="pt-actions">${hasAdd ? `<button class="btn btn-ghost btn-xs" onclick="proposeAdditional()">${st.status === 'extraction_failed' ? 'Retry proposals' : 'Re-propose'}</button>` : ''}</div></div>`;
    const addState = st.status === 'extraction_failed' ? `<span class="badge b-bad">Proposal failed</span> <span class="pnote">${esc(st.error || '')}</span>` : st.status === 'pending' && hasAdd ? '<span class="badge b-muted">Proposing…</span>' : '';
    const addTable = hasAdd ? `<table class="t"><thead><tr><th>Service</th><th>Parent category</th></tr></thead><tbody>${addRows || '<tr><td colspan="2" class="val blank">Nothing parsed yet</td></tr>'}</tbody></table>` : '<div class="val blank">No additional services ticked or typed on the form.</div>';
    return `<div class="prices" id="f_services_resolved"><div class="prices-head"><h3>Categories &amp; services</h3><div class="pt-actions">${primarySel}</div></div>
      <div class="prices-flags">${flagHtml}</div>${tickHtml}
      <div class="pt-actions" style="margin-bottom:.5rem">${tabs}</div>${table}
      ${r.crossRef.length ? `<div class="pnote" style="margin-top:.4rem">${r.crossRef.length} service${r.crossRef.length === 1 ? '' : 's'} on more than one tab: ${esc(r.crossRef.map(x => `${x.name} (${x.short})`).join('; '))}</div>` : ''}
      ${renderServiceOutcomes(s)}
      ${addHead}<div class="prices-flags">${addState}</div>${addTable}</div>`;
  }
  // Launch towns (page map phases): the base town always launches in phase 1; other towns when ticked
  function renderLaunchTowns() {
    // Towns from the record (a string or a list), else from the last page map's inputs
    const f = k => { const x = allFields().find(y => y.key === k); const v = x ? x.value : ''; return Array.isArray(v) ? v.join('\n') : typeof v === 'string' ? v : ''; };
    const fromMap = pm.state && pm.state.inputs;
    const base = (f('primary_town') || (fromMap && fromMap.baseTown) || '').trim();
    const townText = f('other_areas') || (fromMap && fromMap.otherTowns) || '';
    const towns = [...new Set(townText.split(/\r?\n/).map(t => t.replace(/^[\s\-–—*•\d.)]+/, '').trim()).filter(Boolean))].filter(t => slugOf(t) !== slugOf(base));
    const on = new Set(pm.launchTowns || []);
    const published = pm.state && pm.state.phase2_published_at;
    const rows = towns.map(t => `<label class="tick" style="margin:0 1rem .4rem 0;display:inline-flex;gap:.35rem;align-items:center"><input type="checkbox" ${on.has(slugOf(t)) ? 'checked' : ''} ${published ? 'disabled' : ''} onchange="setLaunchTown('${esc(t)}', this.checked)"> ${esc(t)}</label>`).join('');
    return `<div class="prices" id="f_launch_towns"><div class="prices-head"><h3>Launch towns</h3></div>
      <div class="pnote" style="margin-bottom:.5rem">A launch town's location and location category pages go live in phase 1 (published). Other towns' pages are phase 2: built, but draft + noindex, and only linked from other phase 2 pages until you publish phase 2 on <a href="#pages">Pages</a>. Applies the next time the page map is generated.${published ? ` <strong>Phase 2 was published ${esc(fmt(published))}: every page is phase 1.</strong>` : ''}</div>
      <div>${base ? `<span class="badge b-ok" title="The base town always launches in phase 1">${esc(base)} · base town, phase 1</span> ` : ''}${rows || '<span class="pnote">No other towns on the record yet.</span>'}</div></div>`;
  }
  async function setLaunchTown(town, on) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/towns/${encodeURIComponent(town)}/launch`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ launch: on }) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    pm.launchTowns = r.launchTowns; setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500); render();
  }
  async function publishPhase2() {
    const n = pm.rows.filter(r => r.applies && r.info && r.info.phase === 2).length;
    if (!confirm(`Publish phase 2? ${n} page${n === 1 ? '' : 's'} move from draft + noindex to publish, and the links are planned again so phase 1 pages link to them. This cannot be undone here.`)) return;
    setSaved('Publishing…');
    const res = await fetch(`/api/clients/${clientId}/page-map/publish-phase-2`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not done: ' + (r.error || res.status), 'bad'); return; }
    await loadPageMap(); setSaved('Phase 2 published', 'ok'); setTimeout(() => setSaved(''), 2500); render();
  }
  // Which services get a page (page map v3): the niche library's verdict per GBP name first (page as the UK
  // name, absorbed into a page, folded into a category, excluded), then the heuristics for names not in it;
  // Exclude (a person) turns a page into a mention
  function renderServiceOutcomes(s) {
    const lib = (pm.state && pm.state.library) || null;
    const list = lib ? lib.records : ((pm.state && pm.state.services) || null);
    if (lib) return renderLibraryResolution(s, lib);
    const excluded = new Set(pm.excluded || []);
    const catName = k => ((s.allCategories || []).find(c => c.key === k) || {}).name || k;
    const head = `<div class="prices-head" style="margin-top:1rem"><h3>Pages for these services</h3><div class="pt-actions">${list ? `<label class="pnote">Show <select onchange="svcOutcomeFilter=this.value;render()">${[['all', 'All'], ['page', 'Page'], ['merged', 'Merged'], ['folded', 'Folded'], ['mentioned', 'Mentioned']].map(([v, l]) => `<option value="${v}"${svcOutcomeFilter === v ? ' selected' : ''}>${l}${v === 'all' ? '' : ` (${list.filter(x => x.outcome === v).length})`}</option>`).join('')}</select></label>` : ''}</div></div>`;
    if (!list) return `${head}<div class="pnote">Decided when the page map is generated (<a href="#pages">Pages</a>): every service gets its own page unless it is the same service as another, its keyword belongs to a category, or you exclude it here. Search volume sets each page's H1 and copy priority.</div>`;
    const rows = list.filter(x => svcOutcomeFilter === 'all' || x.outcome === svcOutcomeFilter).map(x => {
      const badge = x.outcome === 'page' ? '<span class="badge b-ok">page</span>' : x.outcome === 'merged' ? `<span class="badge b-muted">merged into ${esc(x.intoName || '')}</span>` : x.outcome === 'folded' ? `<span class="badge b-warn">folded into ${esc(x.intoName || '')}</span>` : '<span class="badge b-muted">mentioned</span>';
      const exBox = x.outcome === 'merged' || x.outcome === 'folded' ? '' : `<label class="tick" style="margin:0;white-space:nowrap"><input type="checkbox" ${excluded.has(x.id) ? 'checked' : ''} onchange="setExclude('${esc(x.id)}', this.checked)"> exclude</label>`;
      const prio = x.outcome === 'page' ? `<div class="pnote">copy priority ${x.copy_priority || 0}</div>` : '';
      return `<tr><td>${esc(x.name)}${x.merged_from && x.merged_from.length ? ` <span class="pnote">merged from ${esc(x.merged_from.join(', '))}</span>` : ''}<div class="pnote">${esc((x.parents || []).map(catName).join(', '))}</div></td><td>${badge}<div class="pnote">${esc(x.reason || '')}</div>${prio}</td><td>${exBox}</td></tr>`;
    }).join('');
    const pending = list.filter(x => ['page', 'mentioned'].includes(x.outcome) && excluded.has(x.id) !== (x.outcome === 'mentioned'));
    return `${head}<div class="pnote" style="margin:.2rem 0 .5rem">From the page map generated ${esc(fmt(pm.state.generated_at))}. Every service is a page by default; Exclude lists it on its category page instead. Changes apply the next time the page map is generated.${pending.length ? ` <strong>${pending.length} change${pending.length === 1 ? '' : 's'} not applied yet: regenerate the page map.</strong>` : ''}</div>
      <div class="ctwrap"><table class="t"><thead><tr><th>Service</th><th>Outcome</th><th>Exclude</th></tr></thead><tbody>${rows || '<tr><td colspan="3" class="val blank">Nothing for this filter</td></tr>'}</tbody></table></div>`;
  }
  function renderLibraryResolution(s, lib) {
    const excluded = new Set(pm.excluded || []);
    const catName = k => ((s.allCategories || []).find(c => c.key === k) || {}).name || k;
    const n = o => lib.records.filter(x => x.outcome === o).length;
    const nMissing = lib.records.filter(x => !x.in_library).length, nFlag = lib.records.filter(x => x.flag && x.flag !== 'not in library').length;
    const opts = [['all', `All (${lib.records.length})`], ['page', `Page (${n('page')})`], ['absorbed', `Absorbed (${n('absorbed')})`], ['folded', `Folded (${n('folded')})`], ['excluded', `Excluded (${n('excluded')})`], ['mentioned', `Mentioned (${n('mentioned')})`], ['merged', `Merged (${n('merged')})`], ['missing', `Not in library (${nMissing})`], ['flagged', `Fold target missing (${nFlag})`]];
    const head = `<div class="prices-head" style="margin-top:1rem"><h3>Pages for these services</h3><div class="pt-actions"><label class="pnote">Show <select onchange="svcOutcomeFilter=this.value;render()">${opts.map(([v, l]) => `<option value="${v}"${svcOutcomeFilter === v ? ' selected' : ''}>${l}</option>`).join('')}</select></label></div></div>`;
    const keep = x => svcOutcomeFilter === 'all' || (svcOutcomeFilter === 'missing' ? !x.in_library : svcOutcomeFilter === 'flagged' ? x.flag && x.flag !== 'not in library' : x.outcome === svcOutcomeFilter);
    const rows = lib.records.filter(keep).map(x => {
      const badge = x.outcome === 'page' ? `<span class="badge b-ok">page as ${esc(x.intoName)}</span>` : x.outcome === 'absorbed' ? `<span class="badge b-muted">absorbed into ${esc(x.intoName)}</span>` : x.outcome === 'folded' ? `<span class="badge b-warn">folded into ${esc(x.intoName)}</span>` : x.outcome === 'excluded' ? '<span class="badge b-bad">excluded</span>' : x.outcome === 'mentioned' ? `<span class="badge b-muted">mentioned (${esc(x.intoName)})</span>` : x.outcome === 'merged' ? `<span class="badge b-muted">merged into ${esc(x.intoName)}</span>` : `<span class="badge b-muted">${esc(x.outcome)}</span>`;
      const flags = (x.flag ? `<span class="badge b-warn" title="${x.flag === 'not in library' ? 'Add a verdict to the niche library' : 'The fold target is not one of this client\'s category tabs'}">${esc(x.flag)}</span> ` : '') + (x.verdict ? `<span class="pnote">library: ${esc(x.verdict)}${x.target ? ` → ${esc(x.target)}` : ''}${x.matched && (!x.matched.own || (x.matched.how !== 'name+category' && x.matched.how !== 'name')) ? ` <span class="badge b-muted" title="${esc(x.matched.how)} match of &quot;${esc(x.matched.gbp_name)}&quot; in ${esc(x.matched.file)}">${x.matched.own ? esc(x.matched.how) : esc(x.matched.file)}${x.matched.how === 'fuzzy' ? ` ${Math.round(x.matched.score * 100)}%` : ''}</span>` : ''}${x.fold_lost ? ` <span class="pnote">(fold to ${esc(x.fold_lost.target)} in ${esc(x.fold_lost.file)} passed over: not one of this client's tabs)</span>` : ''}</span>` : '');
      const exBox = x.page_id && ['page', 'mentioned', 'absorbed'].includes(x.outcome) ? `<label class="tick" style="margin:0;white-space:nowrap" title="Exclude the ${esc(x.intoName || x.gbp_name)} page: mentioned on its category page instead"><input type="checkbox" ${excluded.has(x.page_id) ? 'checked' : ''} onchange="setExclude('${esc(x.page_id)}', this.checked)"> exclude page</label>` : '';
      const extra = [x.absorbs && x.absorbs.length && x.outcome === 'page' ? `absorbs ${esc(x.absorbs.join(', '))}` : '', x.outcome === 'page' && x.copy_priority != null ? `copy priority ${x.copy_priority}` : ''].filter(Boolean).join(' · ');
      return `<tr><td>${esc(x.gbp_name)}<div class="pnote">${esc((x.parents || []).map(catName).join(', '))}</div></td><td>${badge} ${flags}${x.note ? `<div class="pnote">${esc(x.note)}</div>` : ''}${x.reason && x.reason !== x.note ? `<div class="pnote">${esc(x.reason)}</div>` : ''}${extra ? `<div class="pnote">${esc(extra)}</div>` : ''}</td><td>${exBox}</td></tr>`;
    }).join('');
    const pending = lib.records.filter(x => x.page_id && ['page', 'mentioned'].includes(x.outcome) && excluded.has(x.page_id) !== (x.outcome === 'mentioned'));
    return `${head}<div class="pnote" style="margin:.2rem 0 .5rem">Each Google Business Profile name against the niche library (${esc(lib.file || '')}), from the page map generated ${esc(fmt(pm.state.generated_at))}: a page under its UK name, absorbed into a page, folded into a category, or excluded. Names not in the library follow the usual rules and are flagged so a verdict can be added. Exclude turns a page into a mention; changes apply the next time the page map is generated.${pending.length ? ` <strong>${pending.length} change${pending.length === 1 ? '' : 's'} not applied yet: regenerate the page map.</strong>` : ''}${(lib.counts && lib.counts.libraryProblems || []).length ? ` <span class="badge b-bad">library problems: ${esc(lib.counts.libraryProblems.join('; '))}</span>` : ''}</div>
      <div class="ctwrap"><table class="t"><thead><tr><th>GBP name</th><th>Resolution</th><th>Exclude</th></tr></thead><tbody>${rows || '<tr><td colspan="3" class="val blank">Nothing for this filter</td></tr>'}</tbody></table></div>`;
  }
  async function setExclude(serviceId, on) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/services/${encodeURIComponent(serviceId)}/exclude`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ excluded: on }) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    pm.excluded = r.excluded; setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500); render();
  }
  async function setPrimary(key) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/services/primary`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ category_key: key || null }) });
    if (!res.ok) { setSaved('Not saved', 'bad'); return; }
    services = await res.json(); setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500); render();
  }
  async function decideAdditional(id, status, categoryKey) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/services/additional/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status, category_key: categoryKey || null }) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    services = r; changing = null; setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500); render();
  }
  async function proposeAdditional() {
    setSaved('Asking for proposals…');
    const res = await fetch(`/api/clients/${clientId}/services/additional/propose`, { method: 'POST' });
    const r = await res.json().catch(() => ({}));
    if (r.view) services = r.view;
    setSaved(r.error ? 'Proposal failed: ' + r.error : 'Proposals updated', r.error ? 'bad' : 'ok'); setTimeout(() => setSaved(''), 3000); render();
  }

  // ── Pages: the page map (page-map/routes.js) ──
  const PM_TYPES = [['homepage', 'Homepage'], ['category', 'Category pages'], ['service', 'Service pages'], ['location', 'Location pages'], ['location_category', 'Location category pages'], ['town_service', 'Town service pages'], ['blog', 'Blog posts']];
  const SECTION_LABEL = { breadcrumb: 'Breadcrumb', cards: 'Cards', areas: 'Areas block', more: 'More services', body: 'Body link', parents: 'Also under' };
  const PM_STATUSES = ['Not Started', 'H1 Added', 'Copy Generated', 'Pushed to WordPress', 'Live'];
  let pm = { rows: [], state: null, excluded: [], launchTowns: [] };   // GET /api/clients/:id/page-map (rows, state, candidates, job, excluded services, launch towns)
  const slugOf = t => String(t || '').toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-');
  let pmPreview = null;                 // GET .../page-map/preview (nothing written)
  let pmConfirm = false;                // the dry-run box is open, waiting for Generate
  let pmRule = 'ticked_only';
  let pmShowRetired = false;
  const pmOpen = new Set(['homepage', 'category']);
  const pmLinksOpen = new Set();       // rows whose links are expanded
  const pmCandOpen = new Set();        // rows whose H1 candidates are expanded
  let pmFilter = 'all';                // all | pattern | conflicts
  let h1Preview = null;                // GET .../h1-research/preview (re-research, waiting for Apply)
  let dfsBalance = null;               // GET /api/dataforseo/balance
  let h1Poll = null;
  let migrationAsked = false;          // the old-rules migration is started once per page load
  async function loadPageMap() {
    try { const res = await fetch(`/api/clients/${clientId}/page-map`); pm = res.ok ? await res.json() : { rows: [], state: null }; } catch (_) { pm = { rows: [], state: null }; }
    pm.candidates = pm.candidates || {};
    if (pm.state && pm.state.category_tab_rule) pmRule = pm.state.category_tab_rule;
    renderH1Bar();
    if (jobActive()) pollH1();
    else migrateOldRules();
  }
  // Old-rules research left on a page map: the current page map and research are applied without a
  // confirmation (Not Started or H1 Added, not manual; later pages get "research now suggests")
  async function migrateOldRules() {
    if (migrationAsked || !pm.rows.some(r => r.applies && h1State(r) === 'old')) return;
    migrationAsked = true;
    try {
      const res = await fetch(`/api/clients/${clientId}/page-map/migrate`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
      const r = await res.json().catch(() => ({}));
      if (res.ok && r.job) { pm.job = r.job; renderH1Bar(); render(); pollH1(); }
    } catch (_) {}
  }
  async function loadPagePreview() {
    try { const res = await fetch(`/api/clients/${clientId}/page-map/preview?rule=${pmRule}`); pmPreview = res.ok ? await res.json() : { error: (await res.json().catch(() => ({}))).error || res.status }; } catch (e) { pmPreview = { error: e.message }; }
    if (current().panel === 'pages') render();
  }
  function renderPageMap() {
    const p = pmPreview;
    const live = pm.rows.filter(r => r.applies), retired = pm.rows.filter(r => !r.applies);
    const head = `<div class="ph"><h2>Pages <span class="tag optional">Page map</span></h2><p>Every page the site needs, planned from the categories, services and towns. H1s come from search volume, or the standard pattern when there is no usable volume; no two pages target the same keyword. Generating again adds and retires pages; it never changes an H1, meta, status or note you set.</p>
      <div class="pc">${live.length ? `${live.length} pages${retired.length ? ` · ${retired.length} no longer apply` : ''}${pm.state && pm.state.generated_at ? ` · generated ${esc(fmt(pm.state.generated_at))}` : ''} · <strong>phase 1: ${live.filter(r => (r.info || {}).phase !== 2).length}</strong> · phase 2: ${live.filter(r => (r.info || {}).phase === 2).length}${pm.state && pm.state.phase2_published_at ? ` (published ${esc(fmt(pm.state.phase2_published_at))})` : ''}` : 'No page map yet'}</div></div>`;
    let facts = '<span>Checking…</span>', canGen = false;
    if (p && p.error) facts = `<span class="badge b-bad">${esc(p.error)}</span>`;
    else if (p) {
      const i = p.inputs, towns = (i.otherTowns || '').split('\n').filter(Boolean).length;
      canGen = i.hasConfig !== false && i.tabs > 0 && !!i.baseTown;
      facts = `<span class="badge ${i.tabs ? 'b-muted' : 'b-bad'}">${i.tabs} category tab${i.tabs === 1 ? '' : 's'}</span><span class="badge ${i.baseTown ? 'b-muted' : 'b-bad'}">Base town: ${esc(i.baseTown || 'missing')}</span><span class="badge b-muted">${towns} other town${towns === 1 ? '' : 's'}</span>`
        + (p.ok && !p.firstRun && (p.diff.counts.wouldAdd || p.diff.counts.wouldRetire || p.diff.counts.wouldUpdate) ? `<span class="badge b-warn">Plan has changed since the last run</span>` : '');
    }
    const ruleSel = `<label class="pnote">Category tabs <select onchange="pmRule=this.value;pmConfirm=false;loadPagePreview()"><option value="ticked_only"${pmRule === 'ticked_only' ? ' selected' : ''}>Ticked only</option><option value="ticked_or_propagated"${pmRule === 'ticked_or_propagated' ? ' selected' : ''}>Ticked or propagated</option></select></label>`;
    const bar = `<div class="pm-bar"><div class="facts">${facts}</div><div class="pt-actions">${ruleSel}
      <button class="btn btn-primary btn-xs" onclick="pmStart()" ${canGen && !jobActive() ? '' : `disabled title="${jobActive() ? 'A page map job is running' : 'Needs at least one category tab and a base town'}"`}>${live.length || retired.length ? 'Regenerate page map' : 'Generate page map'}</button>
      ${live.length ? `<button class="btn btn-ghost btn-xs" onclick="h1Research()" ${jobActive() || (h1Preview && h1Preview.loading) ? 'disabled' : ''} title="Shows what would change first. Never changes a manual H1 or a page at Copy Generated or later">Re-research H1s</button>` : ''}
      ${live.some(r => (r.info || {}).phase === 2) && !(pm.state && pm.state.phase2_published_at) ? `<button class="btn btn-ghost btn-xs" onclick="publishPhase2()" ${jobActive() ? 'disabled' : ''} title="Phase 2 pages become publish and the links are planned again">Publish phase 2</button>` : ''}
      ${pm.rows.length ? `<a class="btn btn-ghost btn-xs" href="/api/clients/${clientId}/page-map.csv">Export CSV</a>` : ''}</div></div>`;
    let box = '';
    const notSetUp = p && p.inputs && p.inputs.hasConfig === false;
    if (notSetUp) box += `<div class="pm-box warn"><h3>Services not set up for this niche yet</h3><div class="pnote">${esc(p.inputs.niche || 'No niche given')} has no services file (fillout/services/), so there are no category tabs to build pages from. Generate page map stays off until the file is added.</div></div>`;
    else if (p && p.ok === false && p.problems) box += `<div class="pm-box warn"><h3>Can't map pages yet</h3><ul>${p.problems.map(x => `<li>${esc(x.msg)}</li>`).join('')}</ul></div>`;
    if (pmConfirm && p && p.ok) box += renderPmConfirm(p);
    if (h1Preview) box += renderH1Preview(h1Preview);
    if (p && p.ok && p.collisions.length) box += `<div class="pm-box warn"><h3>Slug collisions (${p.collisions.length})</h3><ul>${p.collisions.map(c => `<li>${esc(c.msg)}</li>`).join('')}</ul><div class="pnote">Nothing is renamed: fix the name on the record and generate again.</div></div>`;
    if (p && p.ok && p.waiting.length) box += `<div class="pm-box"><h3>Waiting on confirmation (${p.waiting.length})</h3><div class="pnote">Additional services that get a page once confirmed on <a href="#services">Services</a>.</div><ul>${p.waiting.map(w => `<li>${esc(w.service)} <span class="pnote">${esc(w.why)}</span></li>`).join('')}</ul></div>`;
    if (p && p.ok && p.councilAreas.length) box += `<div class="pm-box"><h3>Council areas in the town list</h3><div class="pnote">${esc(p.councilAreas.join(', '))} ${p.councilAreas.length === 1 ? 'is a council area' : 'are council areas'}, not ${p.councilAreas.length === 1 ? 'a town' : 'towns'}. ${p.councilAreas.length === 1 ? 'It has' : 'They have'} pages here, but Copybot's location research skips council areas.</div></div>`;
    // Launch towns live on Areas & Local Details and here, next to the phase counts they drive
    if (live.length) box += `<div class="pm-box" id="pm_launch_towns">${renderLaunchTowns().replace(/^<div class="prices" id="f_launch_towns">/, '').replace(/<\/div>\s*$/, '')}</div>`;
    if (p && p.ok && p.droppedTowns.length) box += `<div class="pm-box"><h3>Towns left out</h3><ul>${p.droppedTowns.map(d => `<li>${esc(d.town)} <span class="pnote">${esc(d.why)}</span></li>`).join('')}</ul></div>`;
    const keep = r => pmFilter === 'all' || (pmFilter === 'conflicts' ? r.applies && r.h1_source === 'conflict' : r.applies && r.h1_source === 'pattern');
    const groups = PM_TYPES.map(([type, label]) => {
      const rows = pm.rows.filter(r => r.type === type && (r.applies || pmShowRetired) && keep(r)).sort((a, b) => (b.applies - a.applies));
      if (pmFilter !== 'all' && !rows.length) return '';
      const n = pm.rows.filter(r => r.type === type && r.applies).length, gone = pm.rows.filter(r => r.type === type && !r.applies).length;
      if (!n && !gone) return '';
      const need = pm.rows.filter(r => r.type === type && r.applies && r.h1_source === 'conflict' && !r.h1).length;
      const pat = pm.rows.filter(r => r.type === type && r.applies && r.h1_source === 'pattern').length;
      return `<details class="pm-group" data-type="${type}"${pmOpen.has(type) ? ' open' : ''} ontoggle="pmToggle('${type}', this.open)"><summary>${esc(label)} <span class="badge b-muted">${n}</span>${need ? `<span class="badge b-bad">${need} H1 conflict${need === 1 ? '' : 's'}</span>` : ''}${pat ? `<span class="badge b-muted">${pat} by pattern</span>` : ''}${gone ? `<span class="badge b-muted">${gone} no longer apply</span>` : ''}</summary>${pmOpen.has(type) ? rows.map(renderPmRow).join('') : ''}</details>`;
    }).join('');
    const retiredToggle = retired.length ? `<div class="pm-bar"><label class="tick" style="margin:0"><input type="checkbox" ${pmShowRetired ? 'checked' : ''} onchange="pmShowRetired=this.checked;render()"> Show pages that no longer apply (${retired.length})</label></div>` : '';
    const nConf = live.filter(r => r.h1_source === 'conflict').length, nPat = live.filter(r => r.h1_source === 'pattern').length;
    const nOld = live.filter(r => h1State(r) === 'old').length;
    const oldBox = nOld ? `<div class="pm-box warn"><h3>${nOld} page${nOld === 1 ? '' : 's'} still carry the old H1 research</h3><div class="pnote">${jobActive() ? 'Moving them to the current rules now: the page map is being rebuilt and researched, and the result is applied to pages at Not Started or H1 Added that are not manual. Pages at Copy Generated or later keep their H1 and get a "research now suggests" note.' : 'They were researched before the current rules (19 Oct). The move to the current rules starts by itself when this page map opens; if it did not, reload the page.'}</div></div>` : '';
    const filterBar = live.length ? `<div class="pm-bar"><label class="pnote">Show <select onchange="pmSetFilter(this.value)"><option value="all"${pmFilter === 'all' ? ' selected' : ''}>All pages</option><option value="conflicts"${pmFilter === 'conflicts' ? ' selected' : ''}>H1 conflicts (${nConf})</option><option value="pattern"${pmFilter === 'pattern' ? ' selected' : ''}>Pattern, no volume data (${nPat})</option></select></label></div>` : '';
    const list = pm.rows.length ? oldBox + filterBar + (groups || '<div class="empty">Nothing to show for this filter.</div>') + retiredToggle : `<div class="empty">No page map yet. ${canGen ? 'Generate it from the categories and towns above.' : notSetUp ? 'This niche needs its services file first.' : 'Add the categories and a base town first.'}</div>`;
    return `<div class="panel">${head}${bar}${box}${list}</div>`;
  }
  function renderPmConfirm(p) {
    const c = p.diff.counts, att = p.inputs.attentionCount;
    const list = (title, items) => items.length ? `<div class="pnote" style="margin-top:.4rem"><strong>${title}:</strong> ${esc(items.slice(0, 12).join(', '))}${items.length > 12 ? ` and ${items.length - 12} more` : ''}</div>` : '';
    return `<div class="pm-box${att ? ' warn' : ''}"><h3>${p.firstRun ? 'Generate the page map?' : 'Dry run: what regenerating will do'}</h3>
      ${att ? `<div>${att} thing${att === 1 ? '' : 's'} on this record need${att === 1 ? 's' : ''} attention (<a href="#overview">Overview</a>). You can still generate; pages update when you generate again.</div>` : ''}
      <div class="counts"><span class="badge b-ok">Would add ${c.wouldAdd}</span><span class="badge ${c.wouldRetire ? 'b-warn' : 'b-muted'}">Would retire ${c.wouldRetire}</span><span class="badge b-muted">Would update links ${c.wouldUpdate}</span><span class="badge b-muted">Unchanged ${c.unchanged}</span></div>
      <div class="pnote">${esc(p.arithmetic)}</div>
      ${p.services ? `<div class="pnote" style="margin-top:.3rem">Services: <strong>${p.services.page}</strong> get a page${p.library && p.library.library ? ` (niche library ${esc(p.library.library)}: ${p.library.absorbed} absorbed, ${p.library.folded} folded, ${p.library.excluded} excluded${p.library.notInLibrary ? `, ${p.library.notInLibrary} not in library` : ''})` : `, ${p.services.merged} merged, ${p.services.folded} folded into a category, ${p.services.mentioned} mentioned only`} · ${p.townServicePages ? `${p.townServicePages.count} town service page${p.townServicePages.count === 1 ? '' : 's'}` : ''}${p.volumesFrom === 'cache' ? ' · from the keyword cache: keywords never looked up count as no volume here; the job looks them up first' : ''}</div>` : ''}
      ${p.phases ? `<div class="pnote">Phase 1: ${p.phases.phase1} pages (publish) · phase 2: ${p.phases.phase2} (draft + noindex)${p.launchTowns && p.launchTowns.length ? ` · launch towns: ${esc(p.launchTowns.join(', '))}` : ''}${p.phase2Published ? ' · phase 2 published' : ''}</div>` : ''}
      ${list('New', p.diff.add)}${list('No longer applies', p.diff.retire)}
      ${p.diff.renames.length ? `<ul>${p.diff.renames.map(r => `<li>${esc(r.msg)}</li>`).join('')}</ul>` : ''}
      ${p.diff.retiringWorkedOn.length ? `<div class="pnote" style="color:var(--warning)">Retiring ${p.diff.retiringWorkedOn.length} page${p.diff.retiringWorkedOn.length === 1 ? '' : 's'} someone has worked on (kept, tagged "no longer applies"): ${esc(p.diff.retiringWorkedOn.slice(0, 8).map(r => `${r.title} (${r.status})`).join(', '))}</div>` : ''}
      <div class="pt-actions" style="margin-top:.6rem"><button class="btn btn-primary btn-xs" onclick="pmGenerate()">${att ? 'Generate anyway' : p.firstRun ? 'Generate' : 'Apply'}</button><button class="btn btn-ghost btn-xs" onclick="pmConfirm=false;render()">Cancel</button></div></div>`;
  }
  // The link planner's sections (page map v3): breadcrumb, cards, areas block, more services, body link, mentioned
  function linkSections(r) {
    const L = r.info && r.info.links;
    if (!L) return `<div class="lcols"><div><h4>Links to</h4>${r.links_to.length ? `<ul>${r.links_to.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<div class="pnote">none</div>'}</div></div>`;
    const secs = Object.keys(SECTION_LABEL).filter(k => (L[k] || []).length).map(k => `<div><h4>${SECTION_LABEL[k]} (${L[k].length})</h4><ul>${L[k].map(x => `<li>${esc(x.anchor)} ${x.unlinked ? `<span class="badge b-muted" title="${esc(x.to)} is phase 2: plain text until phase 2 is published">links when published</span>` : `<span class="pnote">${esc(x.to)}</span>`}</li>`).join('')}</ul></div>`);
    if (r.type === 'town_service') secs.push('<div><h4>Areas block</h4><div class="pnote">villages and neighbourhoods, no links</div></div>');
    if ((L.mentioned || []).length) secs.push(`<div><h4>Mentioned, no link (${L.mentioned.length})</h4><div class="pnote">${esc(L.mentioned.join(', '))}</div></div>`);
    return `<div class="lcols lsec">${secs.join('') || '<div class="pnote">no links out</div>'}</div>`;
  }
  function renderPmRow(r) {
    const linkList = l => l.length ? `<ul>${l.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<div class="pnote">none</div>';
    return `<div class="pm-row${r.applies ? '' : ' retired'}" id="pm_${r.id}">
      <div><div class="ttl">${esc(r.title)}${r.applies ? '' : ' <span class="badge b-muted">no longer applies</span>'}${r.info && r.info.additional ? ' <span class="badge b-ok">additional</span>' : ''}${r.info && r.info.merged_from && r.info.merged_from.length ? ` <span class="badge b-muted" title="One page for names that are the same service">merged from ${esc(r.info.merged_from.join(', '))}</span>` : ''}${r.type === 'service' && r.info && ((r.info.gbp_names || []).some(g => g !== r.title) || (r.info.absorbs || []).length) ? ` <span class="badge b-muted" title="Google Business Profile names behind this page">from ${esc([...(r.info.gbp_names || []).filter(g => g !== r.title), ...(r.info.absorbs || [])].join(', '))}</span>` : ''}${r.type === 'town_service' ? ' <span class="badge b-ok" title="Exists because this service has search volume of its own in this town">town page</span>' : ''}${r.type === 'service' && r.info && r.info.copy_priority != null ? ` <span class="badge b-muted" title="Copy generation orders service pages by this: the service's best search volume, else 0">priority ${r.info.copy_priority}</span>` : ''}${r.info && r.info.phase === 2 ? ' <span class="badge b-warn" title="Draft + noindex until phase 2 is published; linked only from other phase 2 pages">phase 2</span>' : ''}</div><div class="slug">${esc(r.slug)}</div>${r.applies ? '' : `<div class="h1why">No longer applies: ${esc(r.retired_reason || retiredReason(r))}${r.retired_at ? ` (since ${esc(fmt(r.retired_at))})` : ''}. Kept, never deleted; nothing on it changes.</div>`}</div>
      <div><input type="text" value="${esc(r.h1)}" placeholder="${r.h1_source === 'conflict' ? 'H1 conflict: type an H1' : 'H1'}" aria-label="H1 for ${esc(r.title)}" onchange="pmSave('${r.id}', { h1: this.value })">${h1Under(r)}${renderCands(r)}</div>
      <div><select aria-label="Status for ${esc(r.title)}" onchange="pmSave('${r.id}', { status: this.value })">${PM_STATUSES.map(s => `<option${s === r.status ? ' selected' : ''}>${s}</option>`).join('')}</select></div>
      <details class="links"${pmLinksOpen.has(r.id) ? ' open' : ''} ontoggle="if (this.open) pmLinksOpen.add('${r.id}'); else pmLinksOpen.delete('${r.id}')"><summary>Links to ${r.links_to.length} · from ${r.links_from.length}</summary>${linkSections(r)}<div class="lcols"><div><h4>Links from</h4>${linkList(r.links_from)}</div></div></details>
    </div>`;
  }
  // The state of a page's H1, from the row itself (Brandon, 19 Oct 2026):
  //   research  a keyword above 10 searches a month was applied
  //   pattern   no usable keyword: the standard (or hub) pattern was applied
  //   manual    a person's H1
  //   conflict  no usable keyword and the pattern is another page's H1: empty, for a person
  //   old       researched before 19 Oct under the old rules (h1_source "suggested", or "needed"
  //             with a research date): Re-research H1s converts it
  //   none      no research run at all (a page added since, or a map never researched)
  // Same wording as page-map/store.js retiredReason, for rows retired before it was stored
  function retiredReason(r) {
    const t = r.title;
    if (r.type === 'service') return `"${t}" is no longer one of this client's services: it is not ticked in any category on the record`;
    if (r.type === 'category') return `the "${t}" category is no longer one of this client's category tabs`;
    if (r.type === 'location') return `${t} is no longer in this client's town list`;
    if (r.type === 'location_category') return `the category or the town for "${t}" is no longer on the record`;
    return 'it is no longer in the plan built from the record';
  }
  function h1State(r) {
    const s = r.h1_source;
    if (['research', 'pattern', 'manual', 'conflict'].includes(s)) return s;
    if (s === 'suggested' || (r.h1_researched_at && s === 'needed')) return 'old';
    return 'none';
  }
  // The chosen candidate's figures (the row's own, else the candidates table)
  function h1Figures(r) {
    const c = (pm.candidates[r.page_key] || []).find(x => x.chosen) || {};
    return { volume: r.h1_volume != null ? r.h1_volume : c.volume, cpc: r.h1_cpc != null ? Number(r.h1_cpc) : c.cpc };
  }
  function h1Line(r) {
    const st = h1State(r), f = h1Figures(r);
    const fig = () => `${f.volume}/mo · CPC ${f.cpc == null ? 'none' : f.cpc}`;
    if (st === 'research') return `${fig()} · research`;
    if (st === 'pattern') return 'no search data · pattern';
    if (st === 'manual') return 'manual';
    if (st === 'conflict') return 'H1 conflict';
    if (st === 'old') return r.h1_source === 'suggested' && f.volume != null ? `${fig()} · research (old rules)` : 'researched under the old rules: no H1 applied';
    return 'not researched yet';
  }
  // Under the H1: the volume line, why, and notes (hub page, research now suggests, old rules)
  function h1Under(r) {
    if (!r.applies) return '';
    const why = t => t ? `<div class="h1why">${esc(t)}</div>` : '';
    const notes = (r.h1_hub && !String(r.h1_reason || '').includes(r.h1_hub) ? why(r.h1_hub) : '') + (r.h1_suggests ? `<div class="h1why">Research now suggests "${esc(r.h1_suggests)}"</div>` : '');
    const st = h1State(r);
    const cls = { research: 'b-ok', pattern: 'b-warn', manual: 'b-muted', conflict: 'b-bad', old: 'b-warn', none: 'b-muted' }[st];
    const line = `<div class="h1vol"><span class="badge ${cls}">${esc(h1Line(r))}</span></div>`;
    const old = st === 'old' ? '<div class="h1why">Researched on 18 Oct under the old rules. Re-research H1s applies the current ones (patterns for pages without volume, conflicts flagged).</div>' : '';
    return line + (['research', 'pattern', 'conflict'].includes(st) ? why(r.h1_reason) : '') + old + notes;
  }
  function pmSetFilter(v) { pmFilter = v; if (v !== 'all') PM_TYPES.forEach(t => pmOpen.add(t[0])); render(); }
  function renderCands(r) {
    const c = pm.candidates[r.page_key];
    if (!c || !c.length) return '';
    return `<details class="cands"${pmCandOpen.has(r.id) ? ' open' : ''} ontoggle="if (this.open) pmCandOpen.add('${r.id}'); else pmCandOpen.delete('${r.id}')"><summary>Candidates (${c.length})</summary>
      <div class="ctwrap"><table class="ct"><thead><tr><th>Keyword</th><th>Monthly volume</th><th>CPC (currency unconfirmed)</th><th>Why</th></tr></thead><tbody>${c.map(x => `<tr class="${x.chosen ? 'win' : ''}"><td>${x.chosen ? '✓ ' : ''}${esc(x.candidate)}</td><td>${x.volume == null ? 'no data' : x.volume}</td><td>${x.cpc == null ? '—' : x.cpc}</td><td>${esc(x.reason || '')}</td></tr>`).join('')}</tbody></table></div></details>`;
  }
  // ── H1 research job: one-click flow, progress bar at the top, persisted on the server ──
  const jobActive = () => !!(pm.job && ['queued', 'building', 'researching'].includes(pm.job.status));
  const dismissKey = id => 'h1bar_dismissed_' + id;
  function isDismissed(id) { try { return localStorage.getItem(dismissKey(id)) === '1'; } catch (_) { return false; } }
  function dismissH1Bar() { try { localStorage.setItem(dismissKey(pm.job.id), '1'); } catch (_) {} renderH1Bar(); }
  function renderH1Bar() {
    const el = byId('h1bar'); if (!el) return;
    const j = pm.job;
    const low = dfsBalance && dfsBalance.low ? `<span class="badge b-bad" title="DataForSEO account balance">DataForSEO balance $${Number(dfsBalance.balance).toFixed(2)}: below $10, top up before researching</span>` : '';
    const showJob = j && (jobActive() || j.status === 'failed' || (j.status === 'complete' && !j.stale && !isDismissed(j.id)));
    if (!showJob && !low) { el.hidden = true; el.innerHTML = ''; return; }
    let cls = '', txt = '', sub = '', fill = '', btn = '';
    if (showJob && jobActive()) {
      if (j.status === 'building' || (j.status === 'queued' && j.kind === 'generate')) { const pct = j.pages_total ? Math.round(100 * j.pages_built / j.pages_total) : 5; txt = j.pages_total ? `Building pages (${j.pages_built} of ${j.pages_total})` : 'Building pages'; fill = `<div class="fill" style="width:${pct}%"></div>`; }
      else { txt = j.stage || 'Researching H1s'; sub = /is busy/.test(j.stage || '') ? 'Waiting for DataForSEO, which asked us to slow down: this can take up to two minutes' : 'One batched DataForSEO call: this takes a few seconds'; fill = '<div class="fill indet"></div>'; }
    } else if (showJob && j.status === 'complete') { cls = 'ok'; txt = j.stage; fill = '<div class="fill" style="width:100%"></div>'; btn = '<button class="x" onclick="dismissH1Bar()" aria-label="Hide">×</button>'; }
    else if (showJob && j.status === 'failed') { cls = 'bad'; txt = j.stage || 'H1 research failed'; sub = 'The page map is saved; only the H1 research failed.'; fill = '<div class="fill" style="width:100%"></div>'; btn = '<button class="btn btn-primary btn-xs" onclick="h1Retry()">Retry</button>'; }
    el.hidden = false;
    el.innerHTML = `<div class="in ${cls}" role="status" aria-live="polite">${txt ? `<div class="txt">${esc(txt)}${sub ? `<div class="sub">${esc(sub)}</div>` : ''}</div>` : ''}${low}${btn}${fill ? `<div class="track">${fill}</div>` : ''}</div>`;
  }
  function pollH1() {
    if (h1Poll) return;
    h1Poll = setInterval(async () => {
      try {
        const r = await (await fetch(`/api/clients/${clientId}/h1-research`)).json();
        pm.job = r.job; renderH1Bar();
        if (!jobActive()) {
          clearInterval(h1Poll); h1Poll = null;
          await loadPageMap(); if (current().panel === 'pages') loadPagePreview(); render();
        } else if (r.job && r.job.status === 'researching' && !pm.rows.length) { const j = pm.job; await loadPageMap(); pm.job = j; render(); }
      } catch (_) {}
    }, 1500);
  }
  async function startJob(url, body) {
    const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not started: ' + (r.error || res.status), 'bad'); return; }
    pm.job = r.job; pmConfirm = false; renderH1Bar(); render(); pollH1();
  }
  async function h1Research() {
    h1Preview = { loading: true }; render();
    try {
      const res = await fetch(`/api/clients/${clientId}/h1-research/preview`);
      const r = await res.json().catch(() => ({}));
      h1Preview = res.ok ? r : { error: r.error || res.status };
    } catch (e) { h1Preview = { error: e.message }; }
    render();
  }
  async function h1Apply() { h1Preview = null; return startJob(`/api/clients/${clientId}/h1-research`); }
  function renderH1Preview(v) {
    if (v.loading) return '<div class="pm-box"><h3>Re-research H1s</h3><div class="pnote">Working out what would change…</div></div>';
    if (v.error) return `<div class="pm-box warn"><h3>Could not research H1s</h3><div class="pnote">${esc(v.error)}</div><div class="pt-actions" style="margin-top:.6rem"><button class="btn btn-ghost btn-xs" onclick="h1Preview=null;render()">Close</button></div></div>`;
    const label = s => ({ research: 'by volume', pattern: 'pattern', conflict: 'H1 conflict' }[s] || s || 'none');
    const cost = v.fetched ? `${v.fetched} new keyword${v.fetched === 1 ? '' : 's'} looked up ($${Number(v.cost).toFixed(2)}), the rest from the cache` : 'All keywords from the cache, no cost';
    const real = v.changes.filter(c => c.kind === 'real' || !c.kind), minor = v.changes.filter(c => c.kind && c.kind !== 'real');
    const nReal = v.realCount != null ? v.realCount : real.length;
    const row = c => `<tr><td>${esc(c.title)}</td><td>${esc(c.from || '(empty)')}</td><td><strong>${esc(c.to || '(empty)')}</strong>${c.volume != null ? ` · ${c.volume}/mo` : ''} <span class="pnote">${esc(label(c.toSource))}</span><div class="pnote">${esc(c.reason || '')}</div></td></tr>`;
    const table = list => `<div class="ctwrap"><table class="ct"><thead><tr><th>Page</th><th>H1 now</th><th>Would become</th></tr></thead><tbody>${list.map(row).join('')}</tbody></table></div>`;
    const nCase = minor.filter(c => c.kind === 'case').length, nFill = minor.filter(c => c.kind === 'fill').length;
    const minorBox = minor.length ? `<details class="cands" style="margin-top:.5rem"><summary>${minor.length} other update${minor.length === 1 ? '' : 's'}: ${[nCase ? `${nCase} capitalisation only` : '', nFill ? `${nFill} empty H1${nFill === 1 ? '' : 's'} getting the pattern` : ''].filter(Boolean).join(', ')}</summary>${table(minor)}</details>` : '';
    const notes = v.notes.length ? `<div class="pnote" style="margin-top:.5rem"><strong>Not changed (manual, or Copy Generated or later), research now suggests:</strong></div><ul>${v.notes.map(n => `<li>${esc(n.title)}: "${esc(n.h1)}" → "${esc(n.suggests)}"</li>`).join('')}</ul>` : '';
    return `<div class="pm-box"><h3>Re-research H1s: ${nReal ? `${nReal} real change${nReal === 1 ? '' : 's'}` : v.changes.length ? 'no real changes' : 'nothing would change'}${minor.length ? ` <span class="pnote">(+${minor.length} minor)</span>` : ''}</h3>
      <div class="pnote">${esc(cost)}. Only pages with a research or pattern H1 at Not Started or H1 Added change; manual H1s never do.</div>
      ${real.length ? table(real) : ''}${minorBox}${notes}
      <div class="pt-actions" style="margin-top:.6rem">${v.changes.length || v.notes.length ? '<button class="btn btn-primary btn-xs" onclick="h1Apply()">Apply</button>' : ''}<button class="btn btn-ghost btn-xs" onclick="h1Preview=null;render()">Cancel</button></div></div>`;
  }
  function h1Retry() { return startJob(`/api/clients/${clientId}/h1-research/retry`); }
  async function loadBalance() { try { const r = await fetch('/api/dataforseo/balance'); dfsBalance = r.ok ? await r.json() : null; } catch (_) { dfsBalance = null; } renderH1Bar(); }
  function pmToggle(type, open) { if (open === pmOpen.has(type)) return; if (open) pmOpen.add(type); else pmOpen.delete(type); render(); }
  async function pmStart() {
    await loadPagePreview();
    if (!pmPreview || !pmPreview.ok) return;
    // First run with nothing needing attention: no dry run needed
    if (pmPreview.firstRun && !pmPreview.inputs.attentionCount) return pmGenerate();
    pmConfirm = true; render();
  }
  // Build the pages and research H1s in one background job (progress bar at the top)
  async function pmGenerate() { return startJob(`/api/clients/${clientId}/page-map/run`, { rule: pmRule }); }
  async function pmSave(id, body) {
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/page-map/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    pm.rows = pm.rows.map(x => x.id === id ? r : x);
    setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500); render();
  }

  // ── Set up by hand: a client with no Fillout record ──
  let byHand = null;   // GET /api/clients/:id/services/by-hand
  async function loadByHand() {
    try { const res = await fetch(`/api/clients/${clientId}/services/by-hand`); byHand = res.ok ? await res.json() : null; } catch (_) { byHand = null; }
  }
  function renderByHand(b) {
    const nicheSel = `<select id="bh_niche" onchange="bhNiche(this.value)">${b.niche ? '' : '<option value="">Choose a niche</option>'}${b.niches.map(n => `<option${n === (b.niche || b.suggestedNiche) ? ' selected' : ''}>${esc(n)}</option>`).join('')}</select>`;
    const groups = b.groups.map(g => `<details class="bh-group"${g.ticked.length ? ' open' : ''}><summary><span>${esc(g.name)}</span><span class="pnote">${g.ticked.length} of ${g.options.length} ticked</span></summary><div class="bh-opts">${g.options.map(o => `<label><input type="checkbox" data-group="${esc(g.field)}" value="${esc(o)}"${g.ticked.includes(o) ? ' checked' : ''}> ${esc(o)}</label>`).join('')}</div></details>`).join('');
    return `<div class="prices" id="f_by_hand"><div class="prices-head"><h3>Set up by hand</h3><div class="pt-actions"><label class="pnote">Niche ${nicheSel}</label></div></div>
      <div class="pnote">This client has no Fillout record. Tick the services they offer and add the towns; these save as hand edits, so a later form or Reprocess never overwrites them.</div>
      ${b.groups.length ? groups : '<div class="val blank" style="margin-top:.5rem">Choose a niche that has a categories file to see its tick boxes.</div>'}
      <div class="bh-towns"><div><label for="bh_base">Base town</label><input type="text" id="bh_base" value="${esc(b.baseTown)}" placeholder="e.g. Southampton"><label for="bh_company" style="display:block;margin-top:.6rem">Company name</label><input type="text" id="bh_company" value="${esc(b.companyName)}" placeholder="${esc(b.clientName)}"></div>
      <div><label for="bh_towns">Other towns, one per line</label><textarea id="bh_towns" rows="6">${esc(b.otherTowns)}</textarea></div></div>
      <div class="pt-actions" style="margin-top:.7rem"><button class="btn btn-primary btn-xs" onclick="saveByHand()" ${b.groups.length ? '' : 'disabled'}>Save set-up</button></div></div>`;
  }
  async function bhNiche(label) {
    if (!label) return;
    byHand = { ...byHand, niche: label, groups: [] };
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/services/by-hand`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ niche: label }) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500);
    await load();
  }
  async function saveByHand() {
    const ticks = {};
    for (const g of byHand.groups) ticks[g.field] = [...document.querySelectorAll(`#f_by_hand input[type=checkbox]`)].filter(i => i.dataset.group === g.field && i.checked).map(i => i.value);
    const body = { niche: byId('bh_niche').value, ticks, baseTown: byId('bh_base').value, otherTowns: byId('bh_towns').value, companyName: byId('bh_company').value };
    setSaved('Saving…');
    const res = await fetch(`/api/clients/${clientId}/services/by-hand`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const r = await res.json().catch(() => ({}));
    if (!res.ok) { setSaved('Not saved: ' + (r.error || res.status), 'bad'); return; }
    setSaved('Saved', 'ok'); setTimeout(() => setSaved(''), 1500);
    await load();
  }

  // ── Header actions ──
  async function toggleReviewed() {
    await fetch(`/api/clients/${clientId}/reviewed`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reviewed: !rec.client.reviewedAt }) });
    load();
  }
  async function toggleArchived() {
    if (!rec.client.archivedAt && !confirm(`Archive "${rec.client.name}"? It leaves the Clients list; this record is kept.`)) return;
    await fetch(`/api/clients/${clientId}/${rec.client.archivedAt ? 'unarchive' : 'archive'}`, { method: 'POST' });
    load();
  }
  async function reprocess() {
    const last = rec.submissions[0]; if (!last) return;
    setSaved('Reprocessing…');
    const res = await fetch(`/api/fillout/submissions/${last.id}/reprocess`, { method: 'POST' });
    const r = await res.json().catch(() => ({}));
    setSaved(res.ok && !r.error ? 'Reprocessed' : 'Reprocess failed: ' + (r.error || res.status), res.ok && !r.error ? 'ok' : 'bad'); setTimeout(() => setSaved(''), 3000);
    await load();
  }

  // ── Mounted by the new shell (public/app/tabs/record.js and pagemap.js) ──
  window.RecordPanels = {
    mount(container, id, panel) {
      CONTAINER = container; clientId = id; PANEL = panel || 'overview'; FIELD = null; rec = null; editing = null; priceEdit = null;
      if (!container.dataset.rpWired) {
        container.addEventListener('click', e => { const a = e.target.closest('a[href^="#"]'); if (a && a.getAttribute('href').length > 1) { e.preventDefault(); go(a.getAttribute('href').slice(1)); } });
        container.dataset.rpWired = '1';
      }
      return load();
    },
    go, reload: () => load(), current: () => current(), record: () => rec, pageMap: () => pm,
    toggleReviewed: () => toggleReviewed(), toggleArchived: () => toggleArchived(), reprocess: () => reprocess(),
  };
